BBox3d boundingBox(const std::vector<Point3d>& points) {
    if (points.empty()) {
        BoundingBox3 bbox;
        bbox.reset();
        return bbox;
    }

    Point3d min = points[0];
    Point3d max = points[0];

    for (const Point3d& point : points) {
        min = min.min(point);
        max = max.max(point);
    }

    return BoundingBox3(min, max);
}
